package cn.edu.jlu.wechatmerchant.server.application;

import static org.junit.jupiter.api.Assertions.*;
import cn.edu.jlu.wechatmerchant.protocol.*;
import cn.edu.jlu.wechatmerchant.server.support.TransactionFixture;
import cn.edu.jlu.wechatmerchant.server.domain.promotion.*;
import java.nio.file.Path;
import java.sql.SQLException;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

@Timeout(25)
class AfterSaleServiceTest {
    @TempDir Path folder;
    private record Purchase(CheckoutRequest request,OrderSnapshot order){}
    private Purchase buy(TransactionFixture f,boolean two,Long coupon) throws Exception {var cart=f.carts.add(1,1001,2,0);if(two)cart=f.carts.add(1,1002,1,1);var request=f.request(f.buyer,cart,coupon,CartSelection.all(cart));return new Purchase(request,f.orders.checkout(f.buyer,request).order());}
    private ApplyReturnRequest request(long order){return new ApplyReturnRequest(UUID.randomUUID().toString(),order,"不再需要，申请整单退货");}
    @Test void wholeRefundUsesOriginal142AndRestoresOnceWithoutReturningCouponOrRebuildingCart() throws Exception {
        try(var f=new TransactionFixture(folder.resolve("whole.db"))){
            f.sql("UPDATE products SET price_cents=10000 WHERE product_id=1001");new PromotionManagementService(f.db,f.sessions).save(f.admin,new PromotionConfiguration(1001,0,new PromotionTerms(1000,900),f.clock.instant(),f.clock.instant().plusSeconds(3600),true));
            var p=f.coupons.saveDraft(f.admin,new CouponCampaign(0,0,"满150减20",15000,2000,f.clock.millis(),f.clock.millis()+3600000,10,0,false,false),UUID.randomUUID().toString());f.coupons.publish(f.admin,p.campaignId(),p.version());long coupon=f.coupons.claim(f.buyer,p.campaignId()).couponId();var bought=buy(f,false,coupon);var command=request(bought.order().orderId());
            var applied=f.returns.apply(f.buyer,command);assertEquals("REQUESTED",applied.application().status());assertEquals("RETURN_REQUESTED",f.orders.detail(f.buyer,command.orderId()).status());assertEquals(18,f.value("SELECT stock FROM products WHERE product_id=1001"));assertEquals(0,f.value("SELECT count(*) FROM refunds"));
            var approved=f.returns.manage(f.admin,applied.application().afterSaleId(),1,"APPROVE","");assertEquals("APPROVED",approved.status());assertEquals(0,f.value("SELECT count(*) FROM refunds"));assertEquals(18,f.value("SELECT stock FROM products WHERE product_id=1001"));
            f.sql("UPDATE products SET price_cents=1,name='后续改价' WHERE product_id=1001");var completed=f.returns.manage(f.admin,approved.afterSaleId(),2,"COMPLETE","");assertEquals("14200",completed.refundCents().toString());assertEquals(completed,f.returns.manage(f.admin,approved.afterSaleId(),2,"COMPLETE",""));
            assertEquals(20,f.value("SELECT stock FROM products WHERE product_id=1001"));assertEquals("14200",Long.toString(f.value("SELECT CAST(amount_cents AS INTEGER) FROM refunds")));assertEquals(1,f.value("SELECT count(*) FROM refunds"));assertEquals(1,f.value("SELECT used FROM user_coupons"));assertTrue(f.carts.list(1).items().isEmpty());
            var history=f.orders.detail(f.buyer,command.orderId());assertEquals("REFUNDED",history.status());assertEquals(bought.order().paidCents(),history.paidCents());assertEquals(bought.order().items(),history.items());assertEquals("REFUNDED",f.orders.checkout(f.buyer,bought.request()).order().status());assertEquals(1,f.value("SELECT count(*) FROM orders"));
            assertEquals("STATE_CHANGED",f.returns.apply(f.buyer,request(command.orderId())).failureCode());assertEquals(completed,f.returns.byKey(f.buyer,command.returnKey()).application());f.db.initialize();assertEquals(completed,f.returns.history(f.buyer,command.orderId(),20,0).items().getFirst());f.assertConsistent();
        }
    }
    @Test void rejectionPreservesHistoryAndNewApplicationButOldFailedOrSuccessfulKeysNeverReapply() throws Exception {
        try(var f=new TransactionFixture(folder.resolve("reject.db"))){var order=buy(f,false,null).order();var first=request(order.orderId());var requested=f.returns.apply(f.buyer,first).application();var blocked=request(order.orderId());assertEquals("STATE_CHANGED",f.returns.apply(f.buyer,blocked).failureCode());
            assertThrows(IllegalArgumentException.class,() -> f.returns.manage(f.admin,requested.afterSaleId(),1,"REJECT"," "));var rejected=f.returns.manage(f.admin,requested.afterSaleId(),1,"REJECT","需要补充退货原因");assertEquals("COMPLETED",f.orders.detail(f.buyer,order.orderId()).status());assertEquals(rejected,f.returns.manage(f.admin,requested.afterSaleId(),1,"REJECT","需要补充退货原因"));
            assertEquals("STATE_CHANGED",f.returns.apply(f.buyer,blocked).failureCode());assertEquals(rejected,f.returns.apply(f.buyer,first).application());var again=f.returns.apply(f.buyer,request(order.orderId())).application();assertNotEquals(rejected.afterSaleId(),again.afterSaleId());var page=f.returns.history(f.buyer,order.orderId(),1,0);assertTrue(page.hasMore());assertEquals(again,page.items().getFirst());assertEquals(rejected,f.returns.history(f.buyer,order.orderId(),1,1).items().getFirst());assertEquals(0,f.value("SELECT count(*) FROM refunds"));assertEquals(18,f.value("SELECT stock FROM products WHERE product_id=1001"));
            var conflict=new ApplyReturnRequest(first.returnKey(),first.orderId(),"不同原因");assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(AfterSaleService.Rejected.class,() -> f.returns.apply(f.buyer,conflict)).getMessage());
        }
    }
    @Test void sameKeyConcurrentRequestsAndConcurrentCompletionAreIdempotent() throws Exception {
        try(var f=new TransactionFixture(folder.resolve("parallel.db"))){var order=buy(f,false,null).order();var request=request(order.orderId());var applied=AfterSaleServiceTest.<AfterSaleReceipt>race(Collections.nCopies(6,() -> f.returns.apply(f.buyer,request)));for(var r:applied)assertEquals(applied.getFirst(),r);assertEquals(1,f.value("SELECT count(*) FROM after_sales"));var sale=applied.getFirst().application();f.returns.manage(f.admin,sale.afterSaleId(),1,"APPROVE","");var results=AfterSaleServiceTest.<AfterSaleSnapshot>race(Collections.nCopies(6,() -> f.returns.manage(f.admin,sale.afterSaleId(),2,"COMPLETE","")));for(var r:results)assertEquals(results.getFirst(),r);assertEquals(1,f.value("SELECT count(*) FROM refunds"));assertEquals(20,f.value("SELECT stock FROM products WHERE product_id=1001"));f.assertConsistent();}
    }
    @Test void differentApplyKeysAndApproveRejectRaceHaveOnlyOneWinner() throws Exception {
        try(var f=new TransactionFixture(folder.resolve("different.db"))){var order=buy(f,false,null).order();var values=AfterSaleServiceTest.<AfterSaleReceipt>race(List.of(() -> f.returns.apply(f.buyer,request(order.orderId())),() -> f.returns.apply(f.buyer,request(order.orderId()))));assertEquals(1,values.stream().filter(r -> r.application()!=null).count());var sale=values.stream().filter(r -> r.application()!=null).findFirst().orElseThrow().application();
            var results=AfterSaleServiceTest.<String>race(List.of(() -> review(f,sale,"APPROVE",""),() -> review(f,sale,"REJECT","拒绝说明")));assertEquals(1,results.stream().filter(r -> r.equals("STATE_CHANGED")).count());assertEquals(0,f.value("SELECT count(*) FROM refunds"));assertEquals(18,f.value("SELECT stock FROM products WHERE product_id=1001"));assertEquals(1,f.value("SELECT count(*) FROM after_sales"));}
    }
    private String review(TransactionFixture f,AfterSaleSnapshot s,String action,String note) throws Exception {try{return f.returns.manage(f.admin,s.afterSaleId(),1,action,note).status();}catch(AfterSaleService.Rejected ex){return ex.getMessage();}}
    @Test void sqlFailureAfterStockRestoreRollsBackRefundAndBothStatusesThenManualRetrySucceeds() throws Exception {
        try(var f=new TransactionFixture(folder.resolve("sql.db"))){var order=buy(f,true,null).order();var sale=f.returns.apply(f.buyer,request(order.orderId())).application();f.returns.manage(f.admin,sale.afterSaleId(),1,"APPROVE","");f.sql("CREATE TRIGGER fail_refund BEFORE INSERT ON refunds BEGIN SELECT RAISE(ABORT,'test fault'); END");assertThrows(SQLException.class,() -> f.returns.manage(f.admin,sale.afterSaleId(),2,"COMPLETE",""));assertEquals(18,f.value("SELECT stock FROM products WHERE product_id=1001"));assertEquals(14,f.value("SELECT stock FROM products WHERE product_id=1002"));assertEquals(0,f.value("SELECT count(*) FROM refunds"));assertEquals("APPROVED",f.returns.history(f.buyer,order.orderId(),20,0).items().getFirst().status());assertEquals("RETURN_REQUESTED",f.orders.detail(f.buyer,order.orderId()).status());f.sql("DROP TRIGGER fail_refund");f.returns.manage(f.admin,sale.afterSaleId(),2,"COMPLETE","");assertEquals(20,f.value("SELECT stock FROM products WHERE product_id=1001"));assertEquals(15,f.value("SELECT stock FROM products WHERE product_id=1002"));f.assertConsistent();}
    }
    @ParameterizedTest @ValueSource(strings={"MISSING","OVERFLOW"}) void restoreFailureRollsBackAllProductsAndDoesNotChangeApprovedState(String kind) throws Exception {
        try(var f=new TransactionFixture(folder.resolve("restore.db"))){var order=buy(f,true,null).order();var sale=f.returns.apply(f.buyer,request(order.orderId())).application();f.returns.manage(f.admin,sale.afterSaleId(),1,"APPROVE","");f.sql(kind.equals("MISSING")?"DELETE FROM products WHERE product_id=1002":"UPDATE products SET stock=2147483647 WHERE product_id=1002");assertEquals("STOCK_RESTORE_FAILED",assertThrows(AfterSaleService.Rejected.class,() -> f.returns.manage(f.admin,sale.afterSaleId(),2,"COMPLETE","")).getMessage());assertEquals(18,f.value("SELECT stock FROM products WHERE product_id=1001"));assertEquals(0,f.value("SELECT count(*) FROM refunds"));assertEquals(2,f.returns.history(f.buyer,order.orderId(),20,0).items().getFirst().version());}
    }
    @Test void zeroPaidOrderStillRestoresAllUnitsAndWritesOneZeroRefund() throws Exception {
        try(var f=new TransactionFixture(folder.resolve("zero.db"))){new PromotionManagementService(f.db,f.sessions).save(f.admin,new PromotionConfiguration(1001,0,new PromotionTerms(100000,1000),f.clock.instant(),f.clock.instant().plusSeconds(100),true));var order=buy(f,false,null).order();assertEquals(0,order.paidCents().signum());var sale=f.returns.apply(f.buyer,request(order.orderId())).application();f.returns.manage(f.admin,sale.afterSaleId(),1,"APPROVE","");f.returns.manage(f.admin,sale.afterSaleId(),2,"COMPLETE","");assertEquals(0,f.value("SELECT CAST(amount_cents AS INTEGER) FROM refunds"));assertEquals(1,f.value("SELECT count(*) FROM refunds"));assertEquals(20,f.value("SELECT stock FROM products WHERE product_id=1001"));}
    }
    @Test void rolesOwnershipAndDisabledAdminAreCheckedInsideEveryTransaction() throws Exception {
        try(var f=new TransactionFixture(folder.resolve("access.db"))){var order=buy(f,false,null).order();var request=request(order.orderId());assertEquals("NOT_FOUND",f.returns.apply(f.other,request).failureCode());assertThrows(AfterSaleService.Rejected.class,() -> f.returns.history(f.other,order.orderId(),20,0));var sale=f.returns.apply(f.buyer,request).application();assertEquals("NOT_FOUND",f.returns.byKey(f.other,request.returnKey()).failureCode());assertThrows(SecurityException.class,() -> f.returns.manage(f.buyer,sale.afterSaleId(),1,"APPROVE",""));assertThrows(SecurityException.class,() -> f.returns.adminPage(f.buyer,0));assertThrows(SecurityException.class,() -> f.returns.apply(f.admin,request));f.sql("UPDATE users SET enabled=0 WHERE role='ADMIN'");assertThrows(SecurityException.class,() -> f.returns.manage(f.admin,sale.afterSaleId(),1,"APPROVE",""));assertEquals("REQUESTED",f.returns.history(f.buyer,order.orderId(),20,0).items().getFirst().status());}
    }
    @ParameterizedTest @ValueSource(strings={"BEGIN","COMMIT"}) void busyCompletionIsBoundedAndWholeOperationCanBeRetried(String stage) throws Exception {
        try(var f=new TransactionFixture(folder.resolve("busy.db"))){var order=buy(f,false,null).order();var sale=f.returns.apply(f.buyer,request(order.orderId())).application();f.returns.manage(f.admin,sale.afterSaleId(),1,"APPROVE","");try(var lock=stage.equals("BEGIN")?f.db.openImmediateConnection():f.db.openReadOnlyConnection()){lock.setAutoCommit(false);if(stage.equals("COMMIT"))try(var s=lock.createStatement();var r=s.executeQuery("SELECT * FROM products")){assertTrue(r.next());}assertThrows(SQLException.class,() -> f.returns.manage(f.admin,sale.afterSaleId(),2,"COMPLETE",""));lock.rollback();}assertEquals(0,f.value("SELECT count(*) FROM refunds"));assertEquals(18,f.value("SELECT stock FROM products WHERE product_id=1001"));assertEquals("APPROVED",f.returns.history(f.buyer,order.orderId(),20,0).items().getFirst().status());f.returns.manage(f.admin,sale.afterSaleId(),2,"COMPLETE","");assertEquals(20,f.value("SELECT stock FROM products WHERE product_id=1001"));f.assertConsistent();}
    }
    private static <T> List<T> race(List<Callable<T>> actions) throws Exception {var go=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(actions.size())){var futures=new ArrayList<Future<T>>();for(var task:actions)futures.add(pool.submit(() -> {go.await();return task.call();}));go.countDown();var out=new ArrayList<T>();for(var future:futures)out.add(future.get(15,TimeUnit.SECONDS));return out;}}
}
